import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";

const branches = {
  "Nava India": {
    memberships: [
      ["Monthly", "₹4,000"],
      ["3 Months", "₹9,000"],
      ["6 Months", "₹12,000"],
      ["12 Months", "₹18,000"],
    ],
    addons: [
      ["Personal Training (PT)", "₹8,000"],
      ["Zumba Classes", "₹3,000"],
      ["Group Training Classes", "₹4,000"],
    ],
  },
  "RS Puram": {
    memberships: [
      ["Monthly", "₹3,000"],
      ["3 Months", "₹9,000"],
      ["6 Months", "₹12,000"],
      ["12 Months", "₹14,000"],
    ],
    addons: [["Personal Training (PT)", "₹8,000"]],
  },
  "Kovaipudur": {
    memberships: [
      ["Monthly", "₹3,000"],
      ["3 Months", "₹7,000"],
      ["6 Months", "₹9,000"],
      ["12 Months", "₹13,000"],
    ],
    addons: [["Personal Training (PT)", "₹8,000"]],
  },
};

export default function Membership() {
  const [active, setActive] = useState("Nava India");

  // 🔹 Enquiry State
  const [open, setOpen] = useState(false);
  const [intent, setIntent] = useState("");
  const [form, setForm] = useState({
    name: "",
    phone: "",
    email: "",
    message: "",
  });
  const [loading, setLoading] = useState(false);

  const openEnquiry = (type) => {
    setIntent(type);
    setOpen(true);
  };

  const submitEnquiry = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      await fetch("/api/enquiries", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...form,
          branch: active,
          intent,
        }),
      });

      alert("Enquiry submitted successfully!");
      setForm({ name: "", phone: "", email: "", message: "" });
      setOpen(false);
    } catch (err) {
      alert("Something went wrong. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <section
      id="membership"
      className="bg-black text-white py-32 px-6 scroll-mt-28"
    >
      <div className="max-w-6xl mx-auto">

        {/* HEADING */}
        <div className="text-center max-w-3xl mx-auto mb-16">
          <h2 className="text-4xl md:text-5xl font-bold">
            Membership <span className="text-[#e9b21a]">Plans</span>
          </h2>
          <p className="mt-6 text-gray-400">
            Membership pricing varies by location. Select your nearest branch to
            view detailed plans.
          </p>
        </div>

        {/* BRANCH TABS */}
        <div className="flex justify-center gap-4 mb-14 flex-wrap">
          {Object.keys(branches).map((branch) => (
            <button
              key={branch}
              onClick={() => setActive(branch)}
              className={`px-6 py-2 rounded-full border transition
                ${
                  active === branch
                    ? "bg-[#e9b21a] border-[#e9b21a] text-black"
                    : "border-white/20 text-gray-300 hover:border-[#e9b21a]"
                }`}
            >
              {branch}
            </button>
          ))}
        </div>

        {/* PRICING PANEL */}
        <AnimatePresence mode="wait">
          <motion.div
            key={active}
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 30 }}
            transition={{ duration: 0.4 }}
            className="grid md:grid-cols-2 gap-10"
          >
            {/* MEMBERSHIPS */}
            <div className="rounded-2xl border border-white/10 bg-black/60 backdrop-blur p-8">
              <h3 className="text-2xl font-semibold mb-6">
                Gym Memberships
              </h3>

              <ul className="space-y-4">
                {branches[active].memberships.map(([label, price], i) => (
                  <li
                    key={i}
                    className="flex justify-between text-gray-300 border-b border-white/10 pb-3"
                  >
                    <span>{label}</span>
                    <span className="font-medium text-white">{price}</span>
                  </li>
                ))}
              </ul>
            </div>

            {/* ADD ONS + CTA */}
            <div className="rounded-2xl border border-white/10 bg-black/60 backdrop-blur p-8 flex flex-col">
              <h3 className="text-2xl font-semibold mb-6">
                Add-On Services
              </h3>

              <ul className="space-y-4 flex-1">
                {branches[active].addons.map(([label, price], i) => (
                  <li
                    key={i}
                    className="flex justify-between text-gray-300 border-b border-white/10 pb-3"
                  >
                    <span>{label}</span>
                    <span className="font-medium text-white">{price}</span>
                  </li>
                ))}
              </ul>

              {/* CTA */}
              <div className="mt-10 flex flex-col sm:flex-row gap-4">
                <button
                  onClick={() =>
                    openEnquiry(`Membership Enquiry - ${active}`)
                  }
                  className="flex-1 px-6 py-3 rounded-full bg-[#e9b21a] hover:bg-[#d4a318] transition font-medium text-black"
                >
                  Join at {active}
                </button>

                <button
                  onClick={() => openEnquiry("Trial Session")}
                  className="flex-1 px-6 py-3 rounded-full border border-white/20 hover:border-[#e9b21a] transition"
                >
                  Book a Trial Session
                </button>
              </div>
            </div>
          </motion.div>
        </AnimatePresence>

        {/* NOTES */}
        <div className="mt-20 text-sm text-gray-500 max-w-4xl mx-auto space-y-2">
          <p>• Prices are subject to change without prior notice</p>
          <p>• Personal Training is billed separately from memberships</p>
          <p>• Class availability may vary by branch</p>
          <p>
            • Membership benefits and inclusions may vary based on selected plan
            and branch policies
          </p>
        </div>
      </div>

      {/* ENQUIRY MODAL */}
      <AnimatePresence>
        {open && (
          <motion.div
            className="fixed inset-0 z-50 bg-black/80 backdrop-blur flex items-center justify-center px-4"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
          >
            <motion.form
              onSubmit={submitEnquiry}
              initial={{ scale: 0.9, y: 30 }}
              animate={{ scale: 1, y: 0 }}
              exit={{ scale: 0.9, y: 30 }}
              className="w-full max-w-md bg-black border border-white/10 rounded-2xl p-8"
            >
              <h3 className="text-2xl font-semibold mb-2 text-[#e9b21a]">
                {intent}
              </h3>
              <p className="text-sm text-gray-400 mb-6">
                Branch: {active}
              </p>

              <input
                required
                placeholder="Name"
                className="w-full mb-4 px-4 py-3 rounded bg-black border border-white/20"
                value={form.name}
                onChange={(e) =>
                  setForm({ ...form, name: e.target.value })
                }
              />

              <input
                required
                placeholder="Phone"
                className="w-full mb-4 px-4 py-3 rounded bg-black border border-white/20"
                value={form.phone}
                onChange={(e) =>
                  setForm({ ...form, phone: e.target.value })
                }
              />

              <input
                placeholder="Email (optional)"
                className="w-full mb-4 px-4 py-3 rounded bg-black border border-white/20"
                value={form.email}
                onChange={(e) =>
                  setForm({ ...form, email: e.target.value })
                }
              />

              <textarea
                placeholder="Message (optional)"
                rows="3"
                className="w-full mb-6 px-4 py-3 rounded bg-black border border-white/20"
                value={form.message}
                onChange={(e) =>
                  setForm({ ...form, message: e.target.value })
                }
              />

              <div className="flex gap-4">
                <button
                  type="submit"
                  disabled={loading}
                  className="flex-1 py-3 rounded-full bg-[#e9b21a] text-black font-medium"
                >
                  {loading ? "Submitting..." : "Submit Enquiry"}
                </button>
                <button
                  type="button"
                  onClick={() => setOpen(false)}
                  className="flex-1 py-3 rounded-full border border-white/20"
                >
                  Cancel
                </button>
              </div>
            </motion.form>
          </motion.div>
        )}
      </AnimatePresence>
    </section>
  );
}
